  part def Controller {
    in attribute io_0 : Real;
    in attribute io_1 : Boolean;
    in attribute io_2 : Real;
    in attribute io_3 : Real;
    in attribute io_4 : Boolean;
    in attribute io_6 : Integer;
    attribute pageIndex : Integer := 0;
    attribute previousPressed : Boolean := false;
    attribute dhtTempLastValid : Real := 0.0;
    attribute dhtHumLastValid : Real := 0.0;
    attribute reportAccumMs : Integer := 0;
    perform action tick {
      first start;
      then if io_4 {
        first start;
        then assign dhtTempLastValid := io_2;
        then assign dhtHumLastValid := io_3;
      }
      then if ((io_1) and ((not previousPressed))) {
        first start;
        then assign pageIndex := (if pageIndex == 0 ? 1 else (if pageIndex == 1 ? 2 else 0));
      }
      then assign previousPressed := io_1;
      then assign reportAccumMs := reportAccumMs + io_6;
      then if reportAccumMs >= 2000 {
        first start;
        then assign reportAccumMs := reportAccumMs - 2000;
      }
    }
    out attribute io_5 : Integer = (if pageIndex == 0 ? (if io_0 >= 1000.0 ? 9999 else (if io_0 <= 0.0 ? 0 else RealFunctions::floor(io_0))) else (if pageIndex == 1 ? (if io_4 ? RealFunctions::floor(io_2) else RealFunctions::floor(dhtTempLastValid)) else (if io_4 ? RealFunctions::floor(io_3) else RealFunctions::floor(dhtHumLastValid))));
    out attribute serial_0_trigger : Boolean = reportAccumMs >= 2000;
    out attribute serial_0_value_0 : Real = io_0;
    out attribute serial_0_value_1 : Real = (if io_4 ? io_2 else dhtTempLastValid);
    out attribute serial_0_value_2 : Real = (if io_4 ? io_3 else dhtHumLastValid);
  }
  part system : Controller;
}
